#!/bin/sh
set -eu
echo "=== Linking final WASM binary ==="     && em++ -O3 ${WASM_FEATURE_FLAGS} -mno-atomics -fexceptions        /workspace/build/*.o        -L/opt/boost/lib        -L/opt/libsodium/lib        -L/opt/openssl/lib        -lboost_serialization        -lboost_system        -lboost_filesystem        -lboost_chrono        -lboost_program_options        -lboost_regex        -lsodium        -lcrypto        -lssl        --bind        -s WASM=1        -s SHARED_MEMORY=0        -s PTHREAD_POOL_SIZE=0        -s ALLOW_MEMORY_GROWTH=1        -s INITIAL_MEMORY=268435456        -s PROXY_TO_PTHREAD=0        -s DYNAMIC_EXECUTION=0        -s MODULARIZE=1        -s EXPORT_NAME="SalviumWallet"        -s EXPORTED_RUNTIME_METHODS='["ccall","cwrap","FS","getValue","setValue"]'        -s EXPORTED_FUNCTIONS='["_fast_generate_key_derivation","_fast_batch_key_derivations","_donna64_get_version","_malloc","_free"]'        -s ERROR_ON_UNDEFINED_SYMBOLS=1        -s DISABLE_EXCEPTION_CATCHING=0        -s ENVIRONMENT='web,worker,node'        -s ASSERTIONS=0        -o /workspace/build/SalviumWallet.js     && ! grep -Eq 'new Function|(^|[^[:alnum:]_])eval\(' /workspace/build/SalviumWallet.js     && echo "=== WASM build complete ==="
